import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import * as before from '../../../console-fx-architecture-round-3/packages/console-fx/dist/browser/index.js';
import { compileConsole, prepareTextMeasurements } from '../../packages/console-fx/dist/browser/index.js';
import { getPresentationDescriptors } from '../../packages/console-fx/dist/index.js';
import { PRESETS, createPresetExample } from '../../packages/console-fx/dist/presets/index.js';

const observations = [];
function compare(name, scene, options) {
  const oldOutput = before.compileConsole(scene, options);
  const newOutput = compileConsole(scene, options);
  assert.deepEqual(newOutput.args, oldOutput.args, name);
  observations.push({ name, sceneSha256: createHash('sha256').update(JSON.stringify(scene)).digest('hex'), optionsSha256: createHash('sha256').update(JSON.stringify(options)).digest('hex'), argsSha256: createHash('sha256').update(JSON.stringify(newOutput.args)).digest('hex') });
}
for (const preset of PRESETS)
  compare(preset.id, createPresetExample(preset.id), {target:'chromium',renderer:'svg',motion:'reduce'});
for (const descriptor of getPresentationDescriptors()) {
  const scene = createPresetExample(descriptor.id);
  const options = { target:'chromium',renderer:'svg',motion:'reduce',layout:{algorithm:'fit/v1',width:360,maxHeight:400,variant:'compact',overflow:'wrap-then-shrink',minFontSize:12},measurementEnvironment:'synthetic-compact-test/v1' };
  const preflight = prepareTextMeasurements(scene, options);
  assert(preflight.ok);
  const measurements = { kind:'consoleFxMeasurements',measurementVersion:1,environment:options.measurementEnvironment,records:preflight.value.map(request=>({request,advance:request.text.length*request.style.fontSize*.5,inkLeft:0,inkRight:request.text.length*request.style.fontSize*.5,ascent:request.style.fontSize*.75,descent:request.style.fontSize*.15})) };
  compare(`${descriptor.id}/compact`, scene, {...options, measurements});
}
writeFileSync('.artifacts/architecture-round-4/output-parity-results.json', JSON.stringify({before:'0799750',observedAt:new Date().toISOString(),scope:'Compiled SVG arguments only; diagnostics intentionally differ',observations},null,2)+'\n');
console.log(`${observations.length} preset and compact SVG argument arrays are byte-identical to the prior candidate.`);

import { chromium } from '@playwright/test';
import { writeFileSync, readFileSync } from 'node:fs';
const owner = JSON.parse(readFileSync('.artifacts/architecture-round-4/browser-owner.json','utf8'));
const browser = await chromium.connectOverCDP('http://127.0.0.1:9461');
const observations = [];
try {
 for (const destination of ['runner-default', 'owned-windows-profile']) {
  const context = await browser.newContext({acceptDownloads:true});
  try {
   const page = await context.newPage();
   const cdp = await context.newCDPSession(page);
   if (destination === 'owned-windows-profile') {
    const {targetInfo} = await cdp.send('Target.getTargetInfo');
    await cdp.send('Browser.setDownloadBehavior',{behavior:'allowAndName',browserContextId:targetInfo.browserContextId,downloadPath:owner.profile,eventsEnabled:true});
   }
   for (const revoke of ['immediate','retained']) {
    const download = page.waitForEvent('download');
    await page.evaluate(revoke => {
      const url=URL.createObjectURL(new Blob(['{"probe":"owned sample"}'],{type:'application/json'}));
      const anchor=document.createElement('a');anchor.href=url;anchor.download='console-fx-probe.json';anchor.click();
      if(revoke==='immediate') URL.revokeObjectURL(url);
    },revoke);
    const file=await download;
    const failure=await file.failure();
    observations.push({destination,revoke,failure,filename:file.suggestedFilename(), ...(failure===null ? {artifactPath:await file.path()} : {})});
   }
  } finally { await context.close(); }
 }
} finally { await browser.close(); }
writeFileSync('.artifacts/architecture-round-4/download-probe.json', JSON.stringify({observedAt:new Date().toISOString(),observations},null,2)+'\n');
console.log(JSON.stringify(observations,null,2));

import { chromium } from '@playwright/test';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const artifactsDir = mkdtempSync(join(tmpdir(), 'console-fx-native-download-'));
const windowsPath = `\\\\wsl.localhost\\nixos${artifactsDir.replaceAll('/', '\\')}`;
const browser = await chromium.connectOverCDP('http://127.0.0.1:9461',{artifactsDir});
try {
 const context = await browser.newContext({acceptDownloads:true});
 try {
  const page = await context.newPage();
  const cdp = await context.newCDPSession(page);
  const {targetInfo} = await cdp.send('Target.getTargetInfo');
  await cdp.send('Browser.setDownloadBehavior',{behavior:'allowAndName',browserContextId:targetInfo.browserContextId,downloadPath:windowsPath,eventsEnabled:true});
  const pending=page.waitForEvent('download');
  await page.evaluate(()=>{const url=URL.createObjectURL(new Blob(['{"probe":"owned sample"}'],{type:'application/json'})); const anchor=document.createElement('a');anchor.href=url;anchor.download='console-fx-probe.json';anchor.click();URL.revokeObjectURL(url);});
  const file=await pending;
  const failure=await file.failure();
  assert.equal(failure,null);
  let contents='';for await(const chunk of await file.createReadStream())contents+=chunk.toString();
  assert.equal(contents,'{"probe":"owned sample"}');
  const receipt={observedAt:new Date().toISOString(),artifactsDir,windowsPath,failure,filename:file.suggestedFilename(),contents};
  writeFileSync('.artifacts/architecture-round-4/download-bridge-probe.json',JSON.stringify(receipt,null,2)+'\n');
  console.log(JSON.stringify(receipt,null,2));
 }finally{await context.close();}
}finally{await browser.close();}

